async function makeTenant(slug: string, timeZone?: string): Promise<Tenant> {
  const tenant = await createTenant(slug);
  if (timeZone !== undefined) {
    await orgRepo.updateOrg(tenant.org.id, { orgId: tenant.org.id, settings: { timeZone } });
  }
  await usageRepo.recomputeUsage(tenant.org.id);
  return tenant;
}

async function insertIssue(
  tenant: Tenant,
  dueAt: string | null,
  status: IssueStatus = "backlog",
) {
  const number = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
  const issue = await issueRepo.insertIssue(
    issueInput(tenant.org.id, tenant.project.id, { dueAt }),
    tenant.userIds.owner,
    number,
  );
  if (status !== "backlog") await issueRepo.setIssueStatus(tenant.org.id, issue.id, status);
  return issue;
}

describe("the workspace time zone setting", () => {
  it("defaults to UTC for a new workspace", async () => {
    const tenant = await createTenant("tz-default");
    expect(tenant.org.settings.timeZone).toBe("UTC");
    expect((await orgRepo.findOrgById(tenant.org.id))?.settings.timeZone).toBe("UTC");
  });

  it("is stored with the other settings and read back everywhere", async () => {
    const tenant = await createTenant("tz-store");

    const updated = await organizationService.updateOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      settings: { timeZone: "Asia/Tokyo" },
    });

    expect(updated.settings.timeZone).toBe("Asia/Tokyo");
    expect((await orgRepo.findOrgById(tenant.org.id))?.settings.timeZone).toBe("Asia/Tokyo");
    expect((await orgRepo.findOrgBySlug("tz-store"))?.settings.timeZone).toBe("Asia/Tokyo");
    expect((await orgRepo.listOrgsForUser(tenant.userIds.owner))[0]?.settings.timeZone).toBe(
      "Asia/Tokyo",
    );
  });

  it("survives a later update of another setting", async () => {
    const tenant = await createTenant("tz-survive");
    await orgRepo.updateOrg(tenant.org.id, { orgId: tenant.org.id, settings: { timeZone: "Europe/Paris" } });

    const updated = await orgRepo.updateOrg(tenant.org.id, {
      orgId: tenant.org.id,
      settings: { digestHourUtc: 3, timeZone: undefined },
    });

    expect(updated.settings.timeZone).toBe("Europe/Paris");
    expect(updated.settings.digestHourUtc).toBe(3);
  });

  it("refuses a zone Intl does not recognise, changing nothing", async () => {
    const tenant = await createTenant("tz-refuse");
    await orgRepo.updateOrg(tenant.org.id, { orgId: tenant.org.id, settings: { timeZone: "Asia/Tokyo" } });

    await expect(
      orgRepo.updateOrg(tenant.org.id, {
        orgId: tenant.org.id,
        name: "Renamed",
        settings: { digestHourUtc: 4, timeZone: "Mars/Olympus" },
      }),
    ).rejects.toBeInstanceOf(RangeError);

    await expect(
      organizationService.updateOrganization(tenant.actors.owner, {
        orgId: tenant.org.id,
        name: "Renamed",
        settings: { digestHourUtc: 4, timeZone: "Mars/Olympus" },
      }),
    ).rejects.toBeInstanceOf(RangeError);

    const after = await orgRepo.findOrgById(tenant.org.id);
    expect(after?.name).toBe(tenant.org.name);
    expect(after?.settings.timeZone).toBe("Asia/Tokyo");
    expect(after?.settings.digestHourUtc).toBe(tenant.org.settings.digestHourUtc);
  });
});

describe("the overdue counter in the project stats", () => {
  async function overdueCount(tenant: Tenant): Promise<number> {
    const { stats } = await projectService.getProject(
      tenant.actors.member,
      tenant.org.id,
      tenant.project.slug,
    );
    const page = await projectService.listProjects(tenant.actors.member, {
      orgId: tenant.org.id,
      limit: 10,
      cursor: null,
    });
    // Both entry points agree.
    expect(page.items.find((row) => row.project.id === tenant.project.id)?.stats.overdueIssues).toBe(
      stats.overdueIssues,
    );
    return stats.overdueIssues;
  }

  it("counts an issue only once its due day has ended", async () => {
    const tenant = await makeTenant("stats-day");
    await insertIssue(tenant, "2026-03-15T12:00:00.000Z");
    await insertIssue(tenant, "2026-03-15T00:00:00.000Z");
    await insertIssue(tenant, "2026-03-14T23:59:59.000Z");

    vi.useFakeTimers();
    vi.setSystemTime(new Date("2026-03-15T23:59:59.000Z"));
