    vi.setSystemTime(new Date("2026-03-15T20:00:00.000Z"));

    expect(await overdueCount(utc)).toBe(0);
    expect(await overdueCount(tokyo)).toBe(1);
  });

  it("counts only open, unarchived issues that have a due date", async () => {
