describe("the overdue sweep", () => {
  async function sweep(now: Date, ...issues: { id: string }[]): Promise<string[]> {
    resetOverdueTracking();
    const seen: string[] = [];
    detachers.push(
      subscribe("issue.overdue", (payload) => {
        seen.push(payload.issueId);
      }),
    );
    await runOverdueIssueJob(now);
    const wanted = new Set(issues.map((issue) => issue.id));
    return seen.filter((id) => wanted.has(id));
  }

  it("does not announce an issue on the day it is due, whatever the hour", async () => {
    const tenant = await makeTenant("sweep-same-day");
    const early = await insertIssue(tenant, "2026-03-15T00:00:00.000Z");
    const late = await insertIssue(tenant, "2026-03-15T23:59:59.000Z");

    expect(await sweep(new Date("2026-03-15T23:59:59.999Z"), early, late)).toEqual([]);
  });

  it("announces it once the day has ended", async () => {
    const tenant = await makeTenant("sweep-next-day");
    const issue = await insertIssue(tenant, "2026-03-15T23:59:59.000Z");

    expect(await sweep(new Date("2026-03-16T00:00:00.000Z"), issue)).toEqual([issue.id]);
  });

  it("follows each workspace's own clock", async () => {
