  async function activityAt(tenant: Tenant, at: string, summary: string): Promise<void> {
    await activityRepo.insertActivity({
      orgId: tenant.org.id,
      action: "issue.created",
      actorId: null,
      subjectKind: "issue",
      subjectId: "subject",
      projectId: null,
      summary,
      metadata: {},
      occurredAt: at as IsoTimestamp,
    });
  }

  async function remaining(tenant: Tenant): Promise<string[]> {
    const rows = await activityRepo.listActivity({ orgId: tenant.org.id, limit: 100, cursor: null });
    return rows.items.map((row) => row.summary).sort();
  }

  it("cuts off at local midnight, retentionDays calendar days before today", async () => {
    // Free plan: 30 days of retention. Today is 2026-06-01 in Tokyo (and
    // 2026-05-31 in UTC), so the cut-off date is 2026-05-02: local midnight is
    // 2026-05-01T15:00Z.
    const tenant = await makeTenant("retention-tokyo", "Asia/Tokyo");
    await orgRepo.updateOrg(tenant.org.id, { orgId: tenant.org.id });
    await activityAt(tenant, "2026-05-01T14:59:59.000Z", "purged");
    await activityAt(tenant, "2026-05-01T15:00:00.000Z", "kept");

    await runCleanupArchivedJob(new Date("2026-05-31T20:00:00.000Z"));

    expect(await remaining(tenant)).toEqual(["kept"]);
  });

