    // New York, 30 days back from 2026-03-20 is 2026-02-18 (no DST between the
    // two dates), but from 2026-04-05 it is 2026-03-06 → 00:00 EST = 05:00Z,
    // whereas 30 × 24h back from noon EDT would land an hour off.
    const tenant = await makeTenant("retention-ny", "America/New_York");
    await activityAt(tenant, "2026-03-06T04:59:59.000Z", "purged");
    await activityAt(tenant, "2026-03-06T05:00:00.000Z", "kept");

    await runCleanupArchivedJob(new Date("2026-04-05T16:00:00.000Z"));

    expect(await remaining(tenant)).toEqual(["kept"]);
  });
});
